from rules import amount


def solve(data):
    cutoff = data.get("cutoff", 10**9)
    selected = {}

    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue

        if "id" in event:
            identity = ("id", event["id"])
        else:
            identity = ("anonymous", position)

        revision = event.get("revision", 0)
        previous = selected.get(identity)
        if previous is None or revision >= previous[0]:
            selected[identity] = (revision, position, event)

    balances = dict(data.get("opening", {}))
    for _, _, event in selected.values():
        if event.get("void") is True:
            continue

        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = f"{account}|{currency}"
        balances[key] = balances.get(key, 0) + amount(event, data["rounding"])

    return {"balances": balances}

def _round_div(numerator, denominator, mode):
    if mode == "half_up":
        if numerator < 0:
            return -((-numerator + denominator // 2) // denominator)
        return (numerator + denominator // 2) // denominator
    return numerator // denominator


def amount(event, mode):
    gross = event["price"] * event.get("quantity", 1)
    discount_bp = max(0, min(10000, event.get("discount_bp", 0)))
    net = _round_div(gross * (10000 - discount_bp), 10000, mode)

    tax_bp = event.get("tax_bp", 0)
    taxed = net + _round_div(net * tax_bp, 10000, mode)
    if event.get("kind") == "refund":
        return -taxed
    return taxed
